// Webhook-Body lesen (n8n v2 legt JSON-Body unter .body ab; Fallback: root).
const wh = ($("Webhook: smarter-ingest").first() || {}).json || {};
const body = (wh && wh.body && typeof wh.body === "object") ? wh.body : wh;
const filename = String(body.filename || "upload.txt");
let type = String(body.type || "").toLowerCase();
const base64 = String(body.base64 || "");
if (!base64) throw new Error("Ingest: kein base64 im Body");
if (!type) {
  const l = filename.toLowerCase();
  type = l.endsWith(".pdf") ? "pdf" : (l.endsWith(".html") || l.endsWith(".htm")) ? "html" : "txt";
}

function htmlToText(h) {
  return String(h)
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<\/(p|div|section|article|li|tr|h[1-6]|table|ul|ol|blockquote)>/gi, "\n\n")
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/&#0?39;|&apos;/g, "'")
    .replace(/[ \t ]+/g, " ")
    .replace(/[ \t]*\n[ \t]*/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

if (type === "pdf") {
  // PDF -> Extract From File Node (binary property 'data')
  return [{ json: { filename: filename, type: type, isPdf: true }, binary: { data: { data: base64, mimeType: "application/pdf", fileName: filename } } }];
}

const raw = Buffer.from(base64, "base64").toString("utf-8");
// TXT bleibt VERBATIM (Reintext); nur HTML wird zu Text gestrippt.
const text = (type === "html") ? htmlToText(raw) : raw;
return [{ json: { filename: filename, type: type, isPdf: false, text: text } }];

// Text aus Vorbereitung (txt/html) ODER Extract-From-File (pdf, $json.text).
const prep = ($("Datei vorbereiten").first() || {}).json || {};
let text = "";
if ($json && typeof $json.text === "string" && $json.text.trim()) text = $json.text;
else if (typeof prep.text === "string") text = prep.text;
text = String(text || "");

// Zeichen > 0 pruefen (sonst Fehler-Antwort, keine Unit)
if (!text.trim()) {
  return [{ json: { ok: false, units: 0, queueUpdate: {}, error: "kein extrahierbarer Text" } }];
}

const filename = String(prep.filename || "upload.txt");
const base = filename.replace(/\.[^.]+$/, "");
function slug(s) { return String(s || "src").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 40) || "src"; }
function wc(s) { return String(s == null ? "" : s).trim().split(/\s+/).filter(Boolean).length; }

// Zielgroesse je Unit (aus config, sonst 2800 Woerter). Kleiner Text -> genau 1 Unit.
let targetWords = 2800;
try { const cfg = ($("RTDB: config lesen").first() || {}).json; if (cfg && Number(cfg.targetWords)) targetWords = Number(cfg.targetWords); } catch (e) {}

// VERLUSTFREI: an Absatzgrenzen (Leerzeile) nach Zeichen-Offsets schneiden.
// Jede Unit ist eine exakte Teilzeichenkette; Aneinanderreihung == Originaltext.
function splitLossless(t, tw) {
  const bounds = [];
  const re = /\n\s*\n/g; let last = 0, m;
  while ((m = re.exec(t)) !== null) { bounds.push([last, m.index + m[0].length]); last = m.index + m[0].length; }
  bounds.push([last, t.length]);
  const out = []; let curStart = bounds[0][0], curWords = 0;
  for (let i = 0; i < bounds.length; i++) {
    const s = bounds[i][0], e = bounds[i][1];
    const w = wc(t.slice(s, e));
    if (curWords > 0 && curWords + w > tw) { out.push([curStart, s]); curStart = s; curWords = 0; }
    curWords += w;
    if (i === bounds.length - 1) out.push([curStart, e]);
  }
  return out.map(function (p) { return t.slice(p[0], p[1]); });
}

// bestehende max order lesen (Units anhaengen, nicht ueberschreiben)
let maxOrder = 0;
try {
  const q = ($("RTDB: queue lesen").first() || {}).json || {};
  Object.keys(q).forEach(function (k) { const o = Number(q[k] && q[k].order); if (isFinite(o) && o > maxOrder) maxOrder = o; });
} catch (e) {}

const firstLine = (text.split(/\r?\n/).map(function (s) { return s.trim(); }).find(Boolean) || base).slice(0, 120);
const parts = splitLossless(text, targetWords);
const stamp = Date.now();
const sourceId = slug(base) + "_" + stamp;
const queueUpdate = {};
parts.forEach(function (content, i) {
  const w = wc(content);
  const key = slug(base) + "_" + stamp + "_" + i;
  queueUpdate[key] = {
    sourceId: sourceId,
    order: maxOrder + i + 1,
    title: parts.length > 1 ? (firstLine + " (Teil " + (i + 1) + "/" + parts.length + ")") : firstLine,
    content: content,
    estMinutes: Math.max(1, Math.ceil(w / 200)),
    status: "pending"
  };
});
return [{ json: { ok: true, units: parts.length, queueUpdate: queueUpdate } }];
